package main

import "fmt"

const taxRate = 0.06

func main() {
	var name string = "张三"
	age := 18
	var price float64 = 18.5
	quantity := 2
	var paid bool = true

	var subtotal = price * float64(quantity)
	var total = subtotal * (1 + taxRate)

	fmt.Printf("%s 年龄 %d，买了 %d 件，合计 %.2f 元\n", name, age, quantity, total)
	fmt.Printf("类型: %T %T %T\n", age, price, paid)

	if paid {
		fmt.Println("已付款")
	}
}
